import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'

import { listCompanyAccessRequests, reviewCompanyAccessRequest, submitDomainAccessRequest } from '@/lib/onboarding'
import { InviteFlowError } from '@/lib/invites'

type SessionUser = {
  id: string
  role?: string
  companyId?: string | null
}

export async function GET() {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json([])
  }

  if (!user.id || user.role === 'EMPLOYEE') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const requests = await listCompanyAccessRequests(user.companyId)
    return NextResponse.json(requests)
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: 'Failed to load access requests.' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  try {
    const body = (await req.json()) as {
      name?: string
      email?: string
      role?: string
    }

    const request = await submitDomainAccessRequest({
      name: body.name ?? '',
      email: body.email ?? '',
      role: body.role ?? '',
    })

    return NextResponse.json(request, { status: 201 })
  } catch (error) {
    if (error instanceof InviteFlowError) {
      return NextResponse.json({ error: error.message }, { status: error.status })
    }

    console.error(error)
    return NextResponse.json({ error: 'Failed to create access request.' }, { status: 500 })
  }
}

export async function PATCH(req: NextRequest) {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId || !user.id || user.role === 'EMPLOYEE') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const body = (await req.json()) as {
      requestId?: string
      action?: 'APPROVE' | 'REJECT'
      ttlHours?: number
    }

    const result = await reviewCompanyAccessRequest({
      requestId: body.requestId ?? '',
      action: body.action ?? 'REJECT',
      reviewerId: user.id,
      reviewerRole: user.role ?? 'EMPLOYEE',
      companyId: user.companyId,
      ttlHours: body.ttlHours,
    })

    return NextResponse.json(result)
  } catch (error) {
    if (error instanceof InviteFlowError) {
      return NextResponse.json({ error: error.message }, { status: error.status })
    }

    console.error(error)
    return NextResponse.json({ error: 'Failed to review access request.' }, { status: 500 })
  }
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'
import { getAiConversationReplay } from '@/lib/ai-conversation-state'
import { NO_STORE_HEADERS } from '@/lib/http'

type SessionUser = {
  id: string
  name?: string | null
  email?: string | null
  role?: string | null
  companyId?: string | null
}

function cleanConversationId(value: string | null) {
  return value && /^[a-z0-9_-]{8,80}$/i.test(value) ? value : null
}

export async function GET(req: NextRequest) {
  const user = await requireSessionUser()
  if (!user) return NextResponse.json({ error: 'Unauthorized' }, { status: 401, headers: NO_STORE_HEADERS })

  const conversationId = cleanConversationId(req.nextUrl.searchParams.get('conversationId'))
  const replay = await getAiConversationReplay({ user, conversationId })

  return NextResponse.json(replay, { headers: NO_STORE_HEADERS })
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'

import { prisma } from '@/lib/db'
import { commentSelect, getAllowedCommentFile } from '@/lib/media-comments'
import { emitCompanyRealtime } from '@/lib/realtime-server'
import type { SessionUser } from '@/lib/project-access'

type UpdateCommentBody = {
  resolved?: boolean
}

export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await requireSessionUser()
  const { id } = await params
  const existing = await prisma.comment.findUnique({
    where: { id },
    select: { id: true, fileId: true },
  })
  if (!existing) return NextResponse.json({ error: 'Comment not found.' }, { status: 404 })

  const file = await getAllowedCommentFile(existing.fileId, user)
  if (!file) return NextResponse.json({ error: 'Comment not found.' }, { status: 404 })

  const body = (await req.json().catch(() => ({}))) as UpdateCommentBody
  if (typeof body.resolved !== 'boolean') {
    return NextResponse.json({ error: 'resolved must be a boolean.' }, { status: 400 })
  }

  const comment = await prisma.comment.update({
    where: { id },
    data: { resolved: body.resolved },
    select: commentSelect,
  })

  emitCompanyRealtime(user.companyId, 'comment_updated', { fileId: file.id, projectId: file.projectId, comment })

  return NextResponse.json(comment)
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'

import { prisma } from '@/lib/db'
import {
  commentSelect,
  getAllowedCommentFile,
  normalizeCommentContent,
  normalizeTimestamp,
  timestampFitsDuration,
} from '@/lib/media-comments'
import { emitCompanyRealtime } from '@/lib/realtime-server'
import type { SessionUser } from '@/lib/project-access'

type CreateCommentBody = {
  fileId?: string
  content?: string
  timestamp?: number
  parentId?: string | null
}

export async function POST(req: NextRequest) {
  const user = await requireSessionUser()
  const body = (await req.json().catch(() => ({}))) as CreateCommentBody
  const fileId = body.fileId?.trim()
  if (!fileId) return NextResponse.json({ error: 'fileId is required.' }, { status: 400 })

  const file = await getAllowedCommentFile(fileId, user)
  if (!file) return NextResponse.json({ error: 'File not found.' }, { status: 404 })

  const content = normalizeCommentContent(body.content)
  if (!content) return NextResponse.json({ error: 'Comment content is required.' }, { status: 400 })

  let parentId: string | null = null
  let timestamp = normalizeTimestamp(body.timestamp)

  if (body.parentId) {
    const parent = await prisma.comment.findFirst({
      where: { id: body.parentId, fileId: file.id },
      select: { id: true, parentId: true, timestamp: true },
    })
    if (!parent) return NextResponse.json({ error: 'Parent comment not found.' }, { status: 404 })

    parentId = parent.parentId ?? parent.id
    timestamp = parent.timestamp
  }

  if (timestamp === null) return NextResponse.json({ error: 'A valid timestamp is required.' }, { status: 400 })
  if (!timestampFitsDuration(timestamp, file.duration)) {
    return NextResponse.json({ error: 'Comment timestamp is outside the media duration.' }, { status: 400 })
  }

  const comment = await prisma.comment.create({
    data: {
      fileId: file.id,
      userId: user.id,
      content,
      timestamp,
      parentId,
    },
    select: commentSelect,
  })

  emitCompanyRealtime(user.companyId, 'comment_created', { fileId: file.id, projectId: file.projectId, comment })

  return NextResponse.json(comment, { status: 201 })
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'
import { generateContractPdf } from '@/lib/contract-pdf'
import { getContractVersionContent, recordContractDownload } from '@/modules/contracts/contract.service'
import type { SessionUser } from '@/modules/shared/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'
export const maxDuration = 60

type RouteCtx = {
  params: Promise<{ id?: string }>
}

const PDF_SIGNATURE = '%PDF-'

function requestId() {
  return globalThis.crypto?.randomUUID?.() ?? `contract_pdf_${Date.now()}_${Math.random().toString(36).slice(2)}`
}

function jsonHeaders(reqId: string) {
  return {
    'Content-Type': 'application/json',
    'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
    Pragma: 'no-cache',
    Expires: '0',
    'X-Request-Id': reqId,
    'Access-Control-Expose-Headers': 'X-Request-Id',
  }
}

function jsonError(message: string, status: number, reqId: string) {
  return NextResponse.json({ error: message, requestId: reqId }, { status, headers: jsonHeaders(reqId) })
}

function assertPdf(pdf: Uint8Array) {
  const signature = Buffer.from(pdf.slice(0, 5)).toString('ascii')
  if (pdf.byteLength < 5 || signature !== PDF_SIGNATURE) {
    throw new Error(`PDF renderer returned invalid output. byteLength=${pdf.byteLength} signature=${signature}`)
  }
}

function asciiFilename(value: string) {
  const base = value.replace(/[^a-zA-Z0-9._-]/g, '_').replace(/^_+|_+$/g, '') || 'contract'
  return base.slice(0, 120)
}

function encodeRfc5987(value: string) {
  return encodeURIComponent(value).replace(/[!'()*]/g, (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`)
}

function pdfHeaders(contractNumber: string, byteLength: number) {
  const asciiName = `${asciiFilename(contractNumber)}.pdf`
  const utf8Name = `${contractNumber.replace(/[\\/:*?"<>|]+/g, '_').slice(0, 120) || 'contract'}.pdf`

  return {
    'Content-Type': 'application/pdf',
    'Content-Disposition': `attachment; filename="${asciiName}"; filename*=UTF-8''${encodeRfc5987(utf8Name)}`,
    'Content-Length': String(byteLength),
    'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
    Pragma: 'no-cache',
    Expires: '0',
    'X-Content-Type-Options': 'nosniff',
    'Access-Control-Expose-Headers': 'Content-Disposition, Content-Length, X-Request-Id',
  }
}

function pdfResponse(pdf: Uint8Array, contractNumber: string, reqId: string) {
  assertPdf(pdf)
  const body = new ArrayBuffer(pdf.byteLength)
  new Uint8Array(body).set(pdf)

  return new Response(body, {
    status: 200,
    headers: {
      ...pdfHeaders(contractNumber, pdf.byteLength),
      'X-Request-Id': reqId,
    },
  })
}

async function routeParams(context: RouteCtx) {
  try {
    const params = await context.params
    return typeof params?.id === 'string' ? params.id.trim() : ''
  } catch {
    return ''
  }
}

function log(level: 'info' | 'warn' | 'error', message: string, meta: Record<string, unknown>) {
  const payload = { scope: 'contract-pdf-route', ...meta }
  if (level === 'error') console.error(message, payload)
  else if (level === 'warn') console.warn(message, payload)
  else console.info(message, payload)
}

function errorDetails(error: unknown) {
  if (error instanceof Error) {
    return { name: error.name, message: error.message, stack: error.stack }
  }
  return { message: String(error) }
}

export async function GET(req: NextRequest, context: RouteCtx) {
  const reqId = requestId()
  const startedAt = Date.now()
  let contractId = ''
  let phase = 'route-params'

  try {
    contractId = await routeParams(context)
    if (!contractId) return jsonError('Contract id is required.', 400, reqId)

    phase = 'auth'
    const user = await requireSessionUser()
    if (!user) return jsonError('Unauthorized', 401, reqId)

    phase = 'load-contract'
    const versionId = req.nextUrl.searchParams.get('versionId')
    const { contract, version, content } = await getContractVersionContent(user, contractId, versionId)

    phase = 'generate-pdf'
    const pdf = await generateContractPdf(content, {
      requestId: reqId,
      contractId,
      versionId: version.id,
      contractNumber: contract.contractNumber,
      startedAt,
    })

    phase = 'audit'
    await recordContractDownload(user, {
      contractId,
      versionId: version.id,
      requestId: reqId,
      byteLength: pdf.byteLength,
    })

    log('info', 'Contract PDF request completed.', {
      requestId: reqId,
      contractId,
      versionId: version.id,
      byteLength: pdf.byteLength,
      durationMs: Date.now() - startedAt,
    })

    return pdfResponse(pdf, contract.contractNumber, reqId)
  } catch (error) {
    log('error', 'Contract PDF request failed.', {
      requestId: reqId,
      contractId,
      phase,
      durationMs: Date.now() - startedAt,
      error: errorDetails(error),
    })
    return jsonError('Contract PDF could not be generated right now. Please try again in a moment.', 503, reqId)
  }
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'
import type { Prisma } from '@prisma/client'

import { NO_STORE_HEADERS } from '@/lib/http'
import {
  buildStatsCsv,
  buildWorkspaceStatsExport,
  canManageSettings,
  logAdminAction,
  type SettingsSessionUser,
} from '@/lib/settings'
import { prisma } from '@/lib/db'
import { generateStatsPdf } from '@/lib/stats-pdf'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'
export const maxDuration = 60

type ExportFormat = 'json' | 'csv' | 'pdf'

function buildDownloadHeaders(filename: string, contentType: string) {
  const safeFilename = filename.replace(/[^a-zA-Z0-9._-]/g, '_')
  return {
    ...NO_STORE_HEADERS,
    'Content-Type': contentType,
    'Content-Disposition': `attachment; filename="${safeFilename}"; filename*=UTF-8''${encodeURIComponent(safeFilename)}`,
    'X-Content-Type-Options': 'nosniff',
  }
}

function buildJsonHeaders(reqId: string) {
  return {
    ...NO_STORE_HEADERS,
    'Content-Type': 'application/json; charset=utf-8',
    'X-Content-Type-Options': 'nosniff',
    'X-Request-Id': reqId,
  }
}

function requestId() {
  return globalThis.crypto?.randomUUID?.() ?? `stats_${Date.now()}_${Math.random().toString(36).slice(2)}`
}

function getFormat(value: string | null): ExportFormat {
  if (value === 'csv' || value === 'pdf') return value
  return 'json'
}

function errorDetails(error: unknown) {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      code: 'code' in error ? error.code : undefined,
      stack: error.stack,
    }
  }

  return { message: String(error) }
}

function jsonError(message: string, status: number, reqId: string) {
  return NextResponse.json({ error: message, requestId: reqId }, { status, headers: buildJsonHeaders(reqId) })
}

function logStatsExport(level: 'info' | 'warn' | 'error', payload: Record<string, unknown>) {
  const logPayload = {
    scope: 'stats-export',
    ...payload,
  }

  if (level === 'error') console.error('[stats-export]', logPayload)
  else if (level === 'warn') console.warn('[stats-export]', logPayload)
  else console.info('[stats-export]', logPayload)
}

async function logExportAuditSafely(input: {
  companyId: string
  actorId: string
  format: ExportFormat
  totals: Prisma.InputJsonValue
  requestId: string
}) {
  try {
    await logAdminAction(prisma, {
      companyId: input.companyId,
      actorId: input.actorId,
      action: 'STATS_EXPORTED',
      metadata: {
        format: input.format,
        totals: input.totals,
        requestId: input.requestId,
      },
    })
  } catch (error) {
    logStatsExport('warn', {
      requestId: input.requestId,
      companyId: input.companyId,
      format: input.format,
      event: 'audit-log-failed',
      error: errorDetails(error),
    })
  }
}

export async function GET(req: NextRequest) {
  const reqId = requestId()
  const startedAt = Date.now()
  const format = getFormat(req.nextUrl.searchParams.get('format')?.toLowerCase() ?? null)
  let companyId: string | undefined

  try {
    const user = await requireSessionUser()
    if (!user) return jsonError('Unauthorized', 401, reqId)

    if (!user.id) return jsonError('Unauthorized', 401, reqId)
    if (!user.companyId) return jsonError('No company found for this account.', 400, reqId)
    if (!canManageSettings(user.role)) return jsonError('Forbidden', 403, reqId)
    companyId = user.companyId

    logStatsExport('info', {
      requestId: reqId,
      companyId: user.companyId,
      format,
      event: 'export-started',
    })

    const exportData = await buildWorkspaceStatsExport(user.companyId)

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
    if (format === 'csv') {
      const csv = buildStatsCsv(exportData)
      await logExportAuditSafely({
        companyId: user.companyId,
        actorId: user.id,
        format,
        totals: exportData.summary,
        requestId: reqId,
      })

      logStatsExport('info', {
        requestId: reqId,
        companyId: user.companyId,
        format,
        event: 'export-completed',
        byteLength: Buffer.byteLength(csv),
        durationMs: Date.now() - startedAt,
      })

      return new NextResponse(csv, {
        headers: {
          ...buildDownloadHeaders(`taskit-stats-${timestamp}.csv`, 'text/csv; charset=utf-8'),
          'X-Request-Id': reqId,
        },
      })
    }

    if (format === 'pdf') {
      const pdf = await generateStatsPdf(exportData, {
        requestId: reqId,
        companyId: user.companyId,
        startedAt,
      })
      const body = new Uint8Array(pdf)

      await logExportAuditSafely({
        companyId: user.companyId,
        actorId: user.id,
        format,
        totals: exportData.summary,
        requestId: reqId,
      })

      logStatsExport('info', {
        requestId: reqId,
        companyId: user.companyId,
        format,
        event: 'export-completed',
        byteLength: pdf.byteLength,
        durationMs: Date.now() - startedAt,
      })

      return new Response(body, {
        headers: {
          ...buildDownloadHeaders(`taskit-stats-${timestamp}.pdf`, 'application/pdf'),
          'Content-Length': String(pdf.byteLength),
          'X-Request-Id': reqId,
        },
      })
    }

    const json = JSON.stringify(exportData, null, 2)
    await logExportAuditSafely({
      companyId: user.companyId,
      actorId: user.id,
      format,
      totals: exportData.summary,
      requestId: reqId,
    })

    logStatsExport('info', {
      requestId: reqId,
      companyId: user.companyId,
      format,
      event: 'export-completed',
      byteLength: Buffer.byteLength(json),
      durationMs: Date.now() - startedAt,
    })

    return new NextResponse(json, {
      headers: {
        ...buildDownloadHeaders(`taskit-stats-${timestamp}.json`, 'application/json; charset=utf-8'),
        'X-Request-Id': reqId,
      },
    })
  } catch (error) {
    logStatsExport('error', {
      requestId: reqId,
      companyId,
      format,
      event: 'export-failed',
      durationMs: Date.now() - startedAt,
      error: errorDetails(error),
    })
    return jsonError('Failed to export statistics.', 500, reqId)
  }
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'

import { prisma } from '@/lib/db'
import { NO_STORE_HEADERS } from '@/lib/http'
import { COMMENT_TIME_TOLERANCE_SECONDS, commentSelect, getAllowedCommentFile } from '@/lib/media-comments'
import type { SessionUser } from '@/lib/project-access'

export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await requireSessionUser()
  const { id } = await params
  const file = await getAllowedCommentFile(id, user)
  if (!file) return NextResponse.json({ error: 'File not found.' }, { status: 404 })

  const comments = await prisma.comment.findMany({
    where: { fileId: file.id },
    select: commentSelect,
    orderBy: [{ timestamp: 'asc' }, { createdAt: 'asc' }],
  })

  return NextResponse.json(
    { comments, toleranceSeconds: COMMENT_TIME_TOLERANCE_SECONDS },
    { headers: NO_STORE_HEADERS }
  )
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'

import { createCompanyInvite, getInviteTtlHours, InviteFlowError, listCompanyInvites } from '@/lib/invites'
import { emitCompanyRealtime } from '@/lib/realtime-server'

type SessionUser = {
  id: string
  role?: string
  companyId?: string | null
}

export async function GET() {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json([])
  }

  if (user.role === 'EMPLOYEE') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const invites = await listCompanyInvites(user.companyId)
    return NextResponse.json(invites)
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: 'Failed to load invites.' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json({ error: 'No company found for this account.' }, { status: 400 })
  }

  if (!user.id || user.role === 'EMPLOYEE') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const body = (await req.json()) as {
      email?: string
      role?: string
      ttlHours?: number
    }

    const invite = await createCompanyInvite({
      companyId: user.companyId,
      companyAdminId: user.id,
      companyAdminRole: user.role ?? 'EMPLOYEE',
      email: body.email ?? '',
      role: body.role ?? 'EMPLOYEE',
      ttlHours: body.ttlHours ?? getInviteTtlHours(),
    })

    emitCompanyRealtime(user.companyId, 'employee_invited', { invite })

    return NextResponse.json(invite, { status: 201 })
  } catch (error) {
    if (error instanceof InviteFlowError) {
      return NextResponse.json({ error: error.message }, { status: error.status })
    }

    console.error(error)
    return NextResponse.json({ error: 'Failed to create invite.' }, { status: 500 })
  }
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'
import { Prisma } from '@prisma/client'

import { isAgencyCompanyType, normalizeCompanyType } from '@/lib/company-types'
import { emitCompanyRealtime } from '@/lib/realtime-server'
import {
  createProjectCategory,
  findProjectCategories,
  getProjectCategorySupport,
} from '@/lib/project-category-support'

type SessionUser = {
  companyId?: string | null
  role?: string
  companyType?: string | null
}

export async function GET() {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json([])
  }

  if (!isAgencyCompanyType(normalizeCompanyType(user.companyType))) {
    return NextResponse.json([])
  }

  try {
    return NextResponse.json(await findProjectCategories(user.companyId))
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: 'Failed to load categories.' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json({ error: 'No company found for this account.' }, { status: 400 })
  }

  if (user.role === 'EMPLOYEE') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  if (!isAgencyCompanyType(normalizeCompanyType(user.companyType))) {
    return NextResponse.json({ error: 'Categories are only available for agency workspaces.' }, { status: 403 })
  }

  const support = await getProjectCategorySupport()
  if (!support.hasCategoryTable || !support.hasProjectCategoryColumns) {
    return NextResponse.json(
      { error: 'Project categories are not ready. Apply the latest database migration first.' },
      { status: 503 }
    )
  }

  try {
    const body = (await req.json()) as {
      name?: string
      description?: string
    }

    const name = body.name?.trim()
    const description = body.description?.trim()

    if (!name) {
      return NextResponse.json({ error: 'Category name is required.' }, { status: 400 })
    }

    const category = await createProjectCategory({
        companyId: user.companyId,
        name,
        description: description || null,
      })

    emitCompanyRealtime(user.companyId, 'project_category_created', { category })

    return NextResponse.json(category, { status: 201 })
  } catch (error) {
    console.error(error)
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
      return NextResponse.json({ error: 'A category with this name already exists.' }, { status: 409 })
    }

    return NextResponse.json({ error: 'Failed to create category.' }, { status: 500 })
  }
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { getFirebaseProjectDiagnostics } from '@/lib/firebase-admin'
import { isMissingDatabaseObjectError } from '@/lib/prisma-errors'

type SessionUser = {
  id: string
}

type PushTokenBody = {
  token?: string
  previousToken?: string
  client?: {
    projectId?: string | null
    messagingSenderId?: string | null
    appSenderId?: string | null
    notificationPermission?: string | null
    serviceWorkerPath?: string | null
  }
}

export const runtime = 'nodejs'

function pushStorageUnavailable() {
  return NextResponse.json({
    ok: false,
    disabled: true,
    reason: 'push-token-storage-unavailable',
  })
}

function normalizeToken(value?: string) {
  return typeof value === 'string' ? value.trim() : ''
}

function logProjectMismatches(client?: PushTokenBody['client']) {
  const diagnostics = getFirebaseProjectDiagnostics()
  const mismatches = [...diagnostics.mismatches]

  if (client?.projectId && diagnostics.adminProjectId && client.projectId !== diagnostics.adminProjectId) {
    mismatches.push('Posted token was generated with a Firebase project that differs from FIREBASE_PROJECT_ID')
  }

  if (client?.messagingSenderId && client?.appSenderId && client.messagingSenderId !== client.appSenderId) {
    mismatches.push('Posted token sender ID differs from the sender ID encoded in the client app ID')
  }

  if (mismatches.length > 0) {
    console.error('[push-token] Firebase project mismatch detected.', {
      mismatches,
      server: diagnostics,
      client,
    })
  }
}

export async function POST(req: Request) {
  try {
    const user = await requireSessionUser()
    const { token, previousToken, client } = (await req.json()) as PushTokenBody
    const normalizedToken = normalizeToken(token)
    const normalizedPreviousToken = normalizeToken(previousToken)

    if (!normalizedToken) {
      return NextResponse.json({ error: 'Token is required' }, { status: 400 })
    }

    logProjectMismatches(client)

    const userAgent = req.headers.get('user-agent')

    const pushToken = await prisma.pushToken.upsert({
      where: { token: normalizedToken },
      update: {
        userId: user.id,
        userAgent,
        lastUsedAt: new Date(),
      },
      create: {
        token: normalizedToken,
        userId: user.id,
        userAgent,
        lastUsedAt: new Date(),
      },
    })

    if (normalizedPreviousToken && normalizedPreviousToken !== normalizedToken) {
      await prisma.pushToken.deleteMany({
        where: {
          token: normalizedPreviousToken,
          userId: user.id,
        },
      })
    }

    return NextResponse.json({ ok: true, id: pushToken.id })
  } catch (err) {
    console.error(err)
    if (isMissingDatabaseObjectError(err)) {
      return pushStorageUnavailable()
    }

    return NextResponse.json({ error: 'Server error' }, { status: 500 })
  }
}

export async function GET() {
  try {
    const user = await requireSessionUser()
    const tokenCount = await prisma.pushToken.count({
      where: { userId: user.id },
    })

    return NextResponse.json({
      ok: true,
      tokenCount,
      firebase: getFirebaseProjectDiagnostics(),
    })
  } catch (err) {
    console.error(err)
    if (isMissingDatabaseObjectError(err)) {
      return pushStorageUnavailable()
    }

    return NextResponse.json({ error: 'Server error' }, { status: 500 })
  }
}

export async function DELETE(req: Request) {
  try {
    const user = await requireSessionUser()
    const { token } = (await req.json()) as PushTokenBody
    const normalizedToken = normalizeToken(token)

    if (!normalizedToken) {
      return NextResponse.json({ error: 'Token is required' }, { status: 400 })
    }

    await prisma.pushToken.deleteMany({
      where: {
        token: normalizedToken,
        userId: user.id,
      },
    })

    return NextResponse.json({ ok: true })
  } catch (err) {
    console.error(err)
    if (isMissingDatabaseObjectError(err)) {
      return pushStorageUnavailable()
    }

    return NextResponse.json({ error: 'Server error' }, { status: 500 })
  }
}

import { requireSessionUser } from '@/modules/shared/session'
import { NextRequest, NextResponse } from 'next/server'

import { normalizeCompanyType } from '@/lib/company-types'
import { prisma } from '@/lib/db'
import { emitCompanyRealtime } from '@/lib/realtime-server'

type SessionUser = {
  companyId?: string | null
  role?: string
  companyType?: string | null
}

export async function GET() {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json([])
  }

  try {
    const rooms = await prisma.room.findMany({
      where: {
        companyId: user.companyId,
      },
      select: {
        id: true,
        name: true,
        description: true,
        createdAt: true,
        updatedAt: true,
        _count: {
          select: {
            projects: true,
          },
        },
      },
      orderBy: [{ createdAt: 'asc' }],
    })

    return NextResponse.json(
      rooms.map((room) => ({
        id: room.id,
        name: room.name,
        description: room.description,
        createdAt: room.createdAt,
        updatedAt: room.updatedAt,
        projectCount: room._count.projects,
      }))
    )
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: 'Failed to load rooms.' }, { status: 500 })
  }
}

export async function POST(req: NextRequest) {
  const user = await requireSessionUser()
  if (!user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  if (!user.companyId) {
    return NextResponse.json({ error: 'No company found for this account.' }, { status: 400 })
  }

  if (user.role === 'EMPLOYEE') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  if (normalizeCompanyType(user.companyType) !== 'INDUSTRY') {
    return NextResponse.json({ error: 'Rooms are only available for industry workspaces.' }, { status: 403 })
  }

  try {
    const body = (await req.json()) as {
      name?: string
      description?: string
    }

    const name = body.name?.trim()
    const description = body.description?.trim()

    if (!name) {
      return NextResponse.json({ error: 'Room name is required.' }, { status: 400 })
    }

    const room = await prisma.room.create({
      data: {
        companyId: user.companyId,
        name,
        description: description || null,
      },
      select: {
        id: true,
        name: true,
        description: true,
        createdAt: true,
        updatedAt: true,
        _count: {
          select: {
            projects: true,
          },
        },
      },
    })

    const responseRoom = {
      id: room.id,
      name: room.name,
      description: room.description,
      createdAt: room.createdAt,
      updatedAt: room.updatedAt,
      projectCount: room._count.projects,
    }

    emitCompanyRealtime(user.companyId, 'room_created', { room: responseRoom })

    return NextResponse.json(responseRoom, { status: 201 })
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: 'Failed to create room.' }, { status: 500 })
  }
}
